bool changed = mInstance == null;
if (mInstance == null)
    mInstance = (ResourceManager)UnityEngine.Object.FindObjectOfType(typeof(ResourceManager));
if (mInstance == null)
{
    GameObject go = new GameObject("I2ResourceManager", new System.Type[] { typeof(ResourceManager) });
    go.hideFlags = go.hideFlags | HideFlags.HideAndDontSave;
    mInstance = go.GetComponent<ResourceManager>();
    UnityEngine.SceneManagement.SceneManager.sceneLoaded += MyOnLevelWasLoaded;
}
if (changed && Application.isPlaying)
    UnityEngine.Object.DontDestroyOnLoad(mInstance.gameObject);
return mInstance;

if (Sources.Contains(Source))
    return;
Sources.Add(Source);
if (Source.HasGoogleSpreadsheet() && Source.GoogleUpdateFrequency != LanguageSourceData.eGoogleUpdateFrequency.Never && (Callback_AllowSyncFromGoogle == null || Callback_AllowSyncFromGoogle(Source)))
{
    Source.Import_Google_FromCache();
    if (Source.GoogleUpdateDelay > 0f)
        CoroutineManager.Start(Delayed_Import_Google(Source, Source.GoogleUpdateDelay, false));
    else
        Source.Import_Google(false, false);
}
for (int i = 0; i < Source.mLanguages.Count; i++)
    Source.mLanguages[i].SetLoaded(true);
if (Source.mDictionary.Count == 0)
    Source.UpdateDictionary(true);

if (Callback_AllowSyncFromGoogle == null)
    return true;
return Callback_AllowSyncFromGoogle(Source);

